head.b:skin:
/* ============ KabarViral — Tema Berita Modern ============ */
:root{
  --bg:#ffffff; --bg2:#f4f6fb; --card:#ffffff; --text:#131a26; --muted:#67707f;
  --brand:#e11d48; --brand2:#fb4d6d; --brand-dark:#9f1239;
  --ink:#0f172a; --line:#e7eaf1; --radius:14px;
  --shadow:0 12px 32px rgba(15,23,42,.09);
  --header-h:72px;
}
[data-theme="dark"]{
  --bg:#0b101c; --bg2:#0f1626; --card:#141c31; --text:#eef2fb; --muted:#98a2b8;
  --line:#223052; --shadow:0 12px 32px rgba(0,0,0,.45);
}
*{margin:0;padding:0;box-sizing:border-box}
html{scroll-behavior:smooth}
body{background:var(--bg);color:var(--text);font-family:'Inter',system-ui,-apple-system,'Segoe UI',Roboto,sans-serif;font-size:16px;line-height:1.65;transition:background .4s ease,color .4s ease;animation:pageIn .6s ease both}
@keyframes pageIn{from{opacity:0}to{opacity:1}}
img{max-width:100%;height:auto;display:block}
a{color:inherit;text-decoration:none;transition:color .25s}
ul{list-style:none}
.wrap{max-width:1200px;margin:0 auto;padding:0 20px}
::selection{background:var(--brand);color:#fff}

/* ---- Reveal on scroll ---- */
.reveal{opacity:0;transform:translateY(26px);transition:opacity .7s cubic-bezier(.2,.7,.3,1),transform .7s cubic-bezier(.2,.7,.3,1)}
.reveal.visible{opacity:1;transform:none}
.reveal.d1{transition-delay:.08s}.reveal.d2{transition-delay:.16s}.reveal.d3{transition-delay:.24s}

/* ---- Reading progress ---- */
#progressBar{position:fixed;top:0;left:0;height:3px;width:0;background:linear-gradient(90deg,var(--brand),var(--brand2));z-index:9999;transition:width .1s linear}

/* ---- Topbar ---- */
.topbar{background:var(--ink);color:#cbd5e1;font-size:12.5px;padding:8px 0}
.topbar .wrap{display:flex;justify-content:space-between;align-items:center;gap:12px}
.topbar-date{display:flex;align-items:center;gap:8px}
.topbar-date .live-dot{width:8px;height:8px;border-radius:50%;background:#22c55e;animation:pulseDot 1.6s ease-in-out infinite}
@keyframes pulseDot{0%,100%{transform:scale(1);opacity:1}50%{transform:scale(1.6);opacity:.5}}
.topbar-social{display:flex;gap:12px}
.topbar-social a{opacity:.75;font-size:13px}
.topbar-social a:hover{opacity:1;color:#fff;transform:translateY(-2px)}

/* ---- Header ---- */
.site-header{position:sticky;top:0;z-index:900;background:color-mix(in srgb,var(--bg) 88%,transparent);backdrop-filter:blur(14px);-webkit-backdrop-filter:blur(14px);border-bottom:1px solid var(--line);transition:box-shadow .3s}
.site-header.scrolled{box-shadow:0 8px 24px rgba(15,23,42,.10)}
.header-inner{display:flex;align-items:center;gap:22px;height:var(--header-h)}
.logo{font-family:'Poppins',sans-serif;font-weight:800;font-size:28px;letter-spacing:-.5px;white-space:nowrap;animation:logoGlow 4s ease-in-out infinite}
.logo .kabar{color:var(--text)}
.logo .viral{background:linear-gradient(120deg,var(--brand),var(--brand2));-webkit-background-clip:text;background-clip:text;color:transparent}
@keyframes logoGlow{0%,100%{filter:drop-shadow(0 0 0 rgba(225,29,72,0))}50%{filter:drop-shadow(0 0 14px rgba(225,29,72,.35))}}
.main-nav{display:flex;gap:4px;margin-left:8px}
.main-nav a{padding:10px 14px;border-radius:10px;font-weight:600;font-size:14.5px;color:var(--muted);position:relative;overflow:hidden}
.main-nav a::after{content:'';position:absolute;left:14px;right:14px;bottom:6px;height:2px;border-radius:2px;background:linear-gradient(90deg,var(--brand),var(--brand2));transform:scaleX(0);transform-origin:left;transition:transform .3s ease}
.main-nav a:hover{color:var(--text);background:var(--bg2)}
.main-nav a:hover::after{transform:scaleX(1)}
.header-actions{margin-left:auto;display:flex;align-items:center;gap:10px}
.icon-btn{width:42px;height:42px;border-radius:12px;border:1px solid var(--line);background:var(--card);color:var(--text);cursor:pointer;display:flex;align-items:center;justify-content:center;font-size:17px;transition:transform .25s,box-shadow .25s,background .25s}
.icon-btn:hover{transform:translateY(-2px) rotate(-8deg);box-shadow:var(--shadow)}
.search-box{display:flex;align-items:center;background:var(--bg2);border:1px solid var(--line);border-radius:12px;overflow:hidden;transition:box-shadow .25s,border-color .25s}
.search-box:focus-within{border-color:var(--brand);box-shadow:0 0 0 3px rgba(225,29,72,.15)}
.search-box input{border:0;background:transparent;padding:10px 12px;font-size:14px;color:var(--text);width:170px;outline:none}
.search-box button{border:0;background:linear-gradient(120deg,var(--brand),var(--brand2));color:#fff;padding:10px 14px;cursor:pointer;font-size:14px;transition:filter .25s}
.search-box button:hover{filter:brightness(1.12)}
.hamburger{display:none}

/* ---- Breaking ticker ---- */
.ticker{background:linear-gradient(90deg,var(--brand-dark),var(--brand));color:#fff;overflow:hidden;position:relative}
.ticker-inner{display:flex;align-items:stretch}
.ticker-label{display:flex;align-items:center;gap:8px;background:rgba(0,0,0,.28);padding:10px 18px;font-weight:800;font-size:13px;letter-spacing:1.5px;white-space:nowrap;z-index:2}
.ticker-label .tdot{width:9px;height:9px;border-radius:50%;background:#fff;animation:pulseDot 1.2s infinite}
.ticker-view{overflow:hidden;flex:1;display:flex;align-items:center}
.ticker-track{display:flex;gap:56px;white-space:nowrap;padding:10px 0;animation:tickerScroll 38s linear infinite;will-change:transform}
.ticker:hover .ticker-track{animation-play-state:paused}
.ticker-track a{color:#fff;font-size:14px;font-weight:500;opacity:.95}
.ticker-track a:hover{opacity:1;text-decoration:underline}
.ticker-track a::before{content:'●';margin-right:14px;font-size:9px;opacity:.7}
@keyframes tickerScroll{from{transform:translateX(0)}to{transform:translateX(-50%)}}
/* ---- Hero slider ---- */
.hero{margin:26px 0 8px}
.hero-slider{position:relative;border-radius:20px;overflow:hidden;box-shadow:var(--shadow);min-height:380px;background:var(--bg2)}
.hero-slide{position:absolute;inset:0;opacity:0;transform:scale(1.04);transition:opacity .9s ease,transform 1.4s ease;pointer-events:none}
.hero-slide.active{opacity:1;transform:scale(1);pointer-events:auto;z-index:2}
.hero-slide img{width:100%;height:100%;object-fit:cover;position:absolute;inset:0;animation:kenburns 8s ease-in-out infinite alternate}
@keyframes kenburns{from{transform:scale(1)}to{transform:scale(1.12)}}
.hero-slide::after{content:'';position:absolute;inset:0;background:linear-gradient(180deg,rgba(2,6,23,0) 30%,rgba(2,6,23,.82) 100%)}
.hero-cap{position:absolute;left:0;right:0;bottom:0;padding:34px;color:#fff;z-index:3}
.hero-cap .hcat{display:inline-block;background:linear-gradient(120deg,var(--brand),var(--brand2));font-size:12px;font-weight:700;letter-spacing:1px;padding:5px 14px;border-radius:20px;margin-bottom:12px;animation:fadeUp .7s .1s both}
.hero-cap h2{font-family:'Poppins',sans-serif;font-size:clamp(20px,3.4vw,34px);line-height:1.25;font-weight:700;text-shadow:0 2px 18px rgba(0,0,0,.5);animation:fadeUp .7s .22s both}
.hero-cap h2 a:hover{text-decoration:underline}
@keyframes fadeUp{from{opacity:0;transform:translateY(22px)}to{opacity:1;transform:none}}
.hero-nav{position:absolute;top:50%;transform:translateY(-50%);z-index:4;width:46px;height:46px;border-radius:50%;border:0;background:rgba(255,255,255,.16);backdrop-filter:blur(8px);color:#fff;font-size:18px;cursor:pointer;transition:background .25s,transform .25s}
.hero-nav:hover{background:var(--brand);transform:translateY(-50%) scale(1.1)}
.hero-prev{left:16px}.hero-next{right:16px}
.hero-dots{position:absolute;bottom:16px;right:22px;z-index:4;display:flex;gap:8px}
.hero-dots button{width:10px;height:10px;border-radius:50%;border:0;background:rgba(255,255,255,.45);cursor:pointer;transition:all .3s}
.hero-dots button.active{background:#fff;width:28px;border-radius:6px}
.hero-skeleton{position:absolute;inset:0;background:linear-gradient(100deg,var(--bg2) 40%,var(--line) 50%,var(--bg2) 60%);background-size:200% 100%;animation:shimmer 1.4s infinite}
@keyframes shimmer{from{background-position:180% 0}to{background-position:-20% 0}}

/* ---- Section headings ---- */
.section-head{display:flex;align-items:center;gap:14px;margin:34px 0 20px}
.section-head h2{font-family:'Poppins',sans-serif;font-size:22px;font-weight:700;white-space:nowrap}
.section-head h2::before{content:'';display:inline-block;width:8px;height:22px;border-radius:4px;background:linear-gradient(180deg,var(--brand),var(--brand2));margin-right:10px;vertical-align:-3px;animation:barPulse 2s ease-in-out infinite}
@keyframes barPulse{0%,100%{transform:scaleY(1)}50%{transform:scaleY(1.25)}}
.section-line{flex:1;height:1px;background:var(--line)}

/* ---- Layout ---- */
.content-area{display:grid;grid-template-columns:minmax(0,1fr) 320px;gap:30px;align-items:start;padding-bottom:10px}

/* ---- Post cards ---- */
.posts-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(270px,1fr));gap:22px}
.post-card{background:var(--card);border:1px solid var(--line);border-radius:var(--radius);overflow:hidden;box-shadow:0 4px 14px rgba(15,23,42,.05);transition:transform .35s cubic-bezier(.2,.7,.3,1),box-shadow .35s;display:flex;flex-direction:column}
.post-card:hover{transform:translateY(-8px);box-shadow:var(--shadow)}
.card-media{position:relative;display:block;aspect-ratio:16/9;overflow:hidden;background:var(--bg2)}
.card-media img{width:100%;height:100%;object-fit:cover;transition:transform .6s ease}
.post-card:hover .card-media img{transform:scale(1.08)}
.card-media-fallback{display:flex;align-items:center;justify-content:center;height:100%;font-family:'Poppins';font-weight:800;font-size:22px;color:var(--muted);background:linear-gradient(135deg,var(--bg2),var(--line))}
.card-cat{position:absolute;top:12px;left:12px;background:linear-gradient(120deg,var(--brand),var(--brand2));color:#fff;font-size:11.5px;font-weight:700;letter-spacing:.6px;padding:5px 12px;border-radius:20px;box-shadow:0 4px 12px rgba(225,29,72,.4);animation:catFloat 3s ease-in-out infinite}
@keyframes catFloat{0%,100%{transform:translateY(0)}50%{transform:translateY(-3px)}}
.card-body{padding:18px;display:flex;flex-direction:column;gap:10px;flex:1}
.card-title{font-family:'Poppins',sans-serif;font-size:17px;line-height:1.4;font-weight:600}
.card-title a:hover{color:var(--brand)}
.card-meta{font-size:12.5px;color:var(--muted);display:flex;gap:10px;align-items:center}
.card-meta::before{content:'◷'}
.card-snippet{font-size:14px;color:var(--muted);display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
.read-more{margin-top:auto;align-self:flex-start;font-size:13.5px;font-weight:700;color:var(--brand);display:inline-flex;align-items:center;gap:6px}
.read-more::after{content:'→';transition:transform .25s}
.read-more:hover::after{transform:translateX(5px)}

/* ---- Pager ---- */
.blog-pager{display:flex;justify-content:space-between;gap:14px;margin:34px 0}
.blog-pager a{padding:12px 26px;border-radius:12px;background:var(--card);border:1px solid var(--line);font-weight:600;font-size:14.5px;transition:all .3s}
.blog-pager a:hover{background:linear-gradient(120deg,var(--brand),var(--brand2));color:#fff;border-color:transparent;transform:translateY(-2px);box-shadow:0 8px 20px rgba(225,29,72,.35)}

/* ---- Sidebar ---- */
.sidebar{display:flex;flex-direction:column;gap:22px;position:sticky;top:calc(var(--header-h) + 18px)}
.widget{background:var(--card);border:1px solid var(--line);border-radius:var(--radius);padding:20px;box-shadow:0 4px 14px rgba(15,23,42,.05);animation:fadeUp .6s both}
.widget-title{font-family:'Poppins',sans-serif;font-size:16px;font-weight:700;margin-bottom:14px;padding-bottom:10px;border-bottom:2px solid var(--line);position:relative}
.widget-title::after{content:'';position:absolute;left:0;bottom:-2px;width:44px;height:2px;background:linear-gradient(90deg,var(--brand),var(--brand2));border-radius:2px}
.list-label-widget-content ul{display:flex;flex-wrap:wrap;gap:8px}
.list-label-widget-content li a{display:inline-block;background:var(--bg2);border:1px solid var(--line);padding:7px 14px;border-radius:20px;font-size:13px;font-weight:600;color:var(--muted);transition:all .25s}
.list-label-widget-content li a:hover{background:linear-gradient(120deg,var(--brand),var(--brand2));color:#fff;border-color:transparent;transform:translateY(-2px)}
.list-label-widget-content li a span{opacity:.7;font-weight:400}
.pop-item{display:flex;gap:12px;padding:10px 0;border-bottom:1px dashed var(--line);align-items:center;transition:transform .25s}
.pop-item:last-child{border-bottom:0}
.pop-item:hover{transform:translateX(6px)}
.pop-item img{width:74px;height:58px;object-fit:cover;border-radius:10px;flex-shrink:0}
.pop-item .pop-num{font-family:'Poppins';font-weight:800;font-size:24px;color:var(--line);min-width:30px}
.pop-item a{font-size:13.5px;font-weight:600;line-height:1.45}
.pop-item a:hover{color:var(--brand)}
.social-row{display:flex;gap:10px}
.social-row a{flex:1;text-align:center;padding:10px 4px;border-radius:10px;font-size:13px;font-weight:700;color:#fff;transition:transform .25s,filter .25s}
.social-row a:hover{transform:translateY(-3px) scale(1.04);filter:brightness(1.1)}
.soc-wa{background:#25d366}.soc-x{background:#0f1419}.soc-fb{background:#1877f2}.soc-tg{background:#229ed9}

/* ---- Ad slots ---- */
.ad-slot{position:relative;border:2px dashed var(--line);border-radius:var(--radius);background:var(--bg2);min-height:90px;display:flex;align-items:center;justify-content:center;margin:22px 0;overflow:hidden}
.ad-slot::before{content:'';position:absolute;inset:0;background:linear-gradient(100deg,transparent 40%,rgba(255,255,255,.35) 50%,transparent 60%);background-size:200% 100%;animation:shimmer 2.6s infinite;pointer-events:none}
.ad-label{font-size:11px;letter-spacing:2px;color:var(--muted);text-transform:uppercase;font-weight:700}
.ad-leaderboard{min-height:100px}
.ad-sidebar-box{min-height:250px;margin:0}
/* ---- Halaman artikel ---- */
.post-full{background:var(--card);border:1px solid var(--line);border-radius:var(--radius);padding:30px;box-shadow:var(--shadow)}
.breadcrumb{font-size:13px;color:var(--muted);margin-bottom:14px;display:flex;gap:8px;flex-wrap:wrap}
.breadcrumb a:hover{color:var(--brand)}
.breadcrumb .here{color:var(--text);font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:60%}
.post-title{font-family:'Poppins',sans-serif;font-size:clamp(24px,4vw,36px);line-height:1.3;font-weight:800;margin-bottom:14px;animation:fadeUp .6s both}
.post-meta-full{display:flex;flex-wrap:wrap;gap:14px;font-size:13.5px;color:var(--muted);padding-bottom:16px;margin-bottom:8px;border-bottom:1px solid var(--line)}
.pm-labels{display:flex;gap:8px;flex-wrap:wrap}
.pm-labels a{background:var(--bg2);border:1px solid var(--line);padding:3px 12px;border-radius:16px;font-size:12px;font-weight:600}
.pm-labels a:hover{background:var(--brand);color:#fff;border-color:var(--brand)}
.post-body{font-size:17px;line-height:1.85}
.post-body p{margin:0 0 18px}
.post-body h2,.post-body h3{font-family:'Poppins',sans-serif;margin:28px 0 14px;line-height:1.4}
.post-body h2{font-size:24px}.post-body h3{font-size:20px}
.post-body img{border-radius:12px;margin:20px auto;box-shadow:var(--shadow)}
.post-body blockquote{border-left:4px solid var(--brand);background:var(--bg2);padding:16px 20px;border-radius:0 12px 12px 0;margin:20px 0;font-style:italic;animation:fadeUp .6s both}
.post-body ul{margin:0 0 18px 22px;list-style:disc}
.post-body a{color:var(--brand);font-weight:600}
.post-body a:hover{text-decoration:underline}
.share-box{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-top:26px;padding-top:20px;border-top:1px solid var(--line);font-weight:700;font-size:14px}
.sh{padding:9px 18px;border-radius:20px;color:#fff;font-size:13px;font-weight:700;transition:transform .25s,filter .25s}
.sh:hover{transform:translateY(-3px);filter:brightness(1.1)}
.sh.wa{background:#25d366}.sh.x{background:#0f1419}.sh.fb{background:#1877f2}.sh.tg{background:#229ed9}

/* ---- Footer ---- */
.site-footer{background:var(--ink);color:#cbd5e1;margin-top:50px;animation:fadeUp .7s both}
.footer-grid{display:grid;grid-template-columns:1.4fr 1fr 1fr;gap:30px;padding:44px 20px}
.fcol h4{color:#fff;font-family:'Poppins';font-size:16px;margin-bottom:14px}
.fcol a{display:block;padding:6px 0;font-size:14px;opacity:.8;transition:opacity .25s,transform .25s}
.fcol a:hover{opacity:1;color:#fff;transform:translateX(5px)}
.fdesc{font-size:14px;opacity:.75;margin-top:12px;max-width:320px}
.footer-bottom{text-align:center;padding:16px;font-size:13px;border-top:1px solid rgba(255,255,255,.1);opacity:.7}

/* ---- Back to top ---- */
#backTop{position:fixed;right:22px;bottom:22px;width:50px;height:50px;border-radius:50%;border:0;background:linear-gradient(135deg,var(--brand),var(--brand2));color:#fff;font-size:20px;cursor:pointer;box-shadow:0 10px 24px rgba(225,29,72,.45);opacity:0;transform:translateY(20px) scale(.8);transition:all .35s;z-index:950}
#backTop.show{opacity:1;transform:none}
#backTop:hover{transform:translateY(-4px) scale(1.06)}

/* ---- Responsive ---- */
@media(max-width:960px){
  .content-area{grid-template-columns:1fr}
  .sidebar{position:static}
  .main-nav{position:fixed;top:0;right:-280px;width:260px;height:100vh;background:var(--card);flex-direction:column;padding:90px 20px 20px;gap:6px;box-shadow:-10px 0 30px rgba(0,0,0,.15);transition:right .4s cubic-bezier(.2,.7,.3,1);z-index:960;margin:0}
  .main-nav.open{right:0}
  .main-nav a{padding:14px;font-size:16px}
  .hamburger{display:flex}
  .search-box input{width:110px}
  .footer-grid{grid-template-columns:1fr 1fr}
}
@media(max-width:640px){
  .topbar-social{display:none}
  .search-box{display:none}
  .hero-slider{min-height:280px}
  .logo{font-size:23px}
  .post-full{padding:20px}
  .footer-grid{grid-template-columns:1fr}
  .ticker-label{padding:10px 12px;font-size:11px}
}

body.script:
//
(function(){
  "use strict";
  var $ = function(s,c){ return (c||document).querySelector(s); };
  var $$ = function(s,c){ return Array.prototype.slice.call((c||document).querySelectorAll(s)); };

  /* Tanggal Indonesia */
  try{
    var d = new Date();
    $('#topbarDate').textContent = d.toLocaleDateString('id-ID',{weekday:'long',day:'numeric',month:'long',year:'numeric'});
    var y = $('#yearNow'); if(y) y.textContent = d.getFullYear();
  }catch(e){}

  /* Dark mode */
  var root = document.documentElement, tgl = $('#themeToggle');
  function setTheme(t){ root.setAttribute('data-theme', t); try{localStorage.setItem('kv-theme',t);}catch(e){}
    if(tgl) tgl.textContent = (t==='dark') ? '☀️' : '🌙'; }
  try{ setTheme(localStorage.getItem('kv-theme') || 'light'); }catch(e){ setTheme('light'); }
  if(tgl) tgl.addEventListener('click', function(){
    setTheme(root.getAttribute('data-theme')==='dark' ? 'light' : 'dark');
  });

  /* Header shadow + back-to-top + progress */
  var header = $('#siteHeader'), backTop = $('#backTop'), prog = $('#progressBar'), postBody = $('#postBody');
  function onScroll(){
    var y = window.scrollY || window.pageYOffset;
    if(header) header.classList.toggle('scrolled', y > 10);
    if(backTop) backTop.classList.toggle('show', y > 600);
    if(prog){
      if(postBody){
        var h = document.documentElement;
        var max = h.scrollHeight - h.clientHeight;
        prog.style.width = (max > 0 ? (y/max*100) : 0) + '%';
      } else { prog.style.width = '0'; }
    }
  }
  window.addEventListener('scroll', onScroll, {passive:true}); onScroll();
  if(backTop) backTop.addEventListener('click', function(){ window.scrollTo({top:0, behavior:'smooth'}); });

  /* Mobile menu */
  var nav = $('#mainNav'), burger = $('#menuToggle');
  if(burger && nav) burger.addEventListener('click', function(e){ e.stopPropagation(); nav.classList.toggle('open'); });
  document.addEventListener('click', function(e){
    if(nav && nav.classList.contains('open') && !nav.contains(e.target)) nav.classList.remove('open');
  });

  /* Reveal on scroll */
  var io = ('IntersectionObserver' in window) ? new IntersectionObserver(function(es){
    es.forEach(function(en){ if(en.isIntersecting){ en.target.classList.add('visible'); io.unobserve(en.target); } });
  }, {threshold:.12}) : null;
  function watchReveals(){ $$('.reveal:not(.visible)').forEach(function(el){ if(io) io.observe(el); else el.classList.add('visible'); }); }
  watchReveals();

  /* JSON feed helper */
  function feed(url){
    return fetch(url).then(function(r){ if(!r.ok) throw 0; return r.json(); })
      .then(function(j){ return (j.feed && j.feed.entry) ? j.feed.entry : []; })
      .catch(function(){ return []; });
  }
  function thumb(en, size){
    try{
      var t = en.media$thumbnail && en.media$thumbnail.url;
      if(t) return t.replace(/\/s72-c\//, '/' + (size||'s600') + '/');
    }catch(e){}
    return '';
  }
  function linkOf(en){
    var ls = en.link || [];
    for(var i=0;i<ls.length;i++){ if(ls[i].rel === 'alternate') return ls[i].href; }
    return '#';
  }
  function titleOf(en){ return (en.title && en.title.$t) || 'Tanpa judul'; }
  function labelOf(en){
    try{
      var cs = en.category || [];
      if(cs.length) return cs[0].term;
    }catch(e){}
    return 'Berita';
  }

  /* Breaking ticker */
  var track = $('#tickerTrack');
  if(track){
    feed('/feeds/posts/default?alt=json&max-results=7').then(function(es){
      if(!es.length){ var tb=$('#tickerBox'); if(tb) tb.style.display='none'; return; }
      var html = es.map(function(en){
        return '<a href="' + linkOf(en) + '">' + titleOf(en).replace(/</g,'&lt;') + '</a>';
      }).join('');
      track.innerHTML = html + html; /* duplikat agar loop mulus */
    });
  }

  /* Hero slider */
  var slider = $('#heroSlider');
  if(slider){
    feed('/feeds/posts/default?alt=json&max-results=5').then(function(es){
      var sk = $('#heroSkeleton'); if(sk) sk.style.display = 'none';
      if(!es.length){ slider.style.display='none'; return; }
      es.forEach(function(en, i){
        var s = document.createElement('div');
        s.className = 'hero-slide' + (i===0 ? ' active' : '');
        var im = thumb(en,'s1600');
        s.innerHTML =
          (im ? '<img src="' + im + '" alt=""/>' : '') +
          '<div class="hero-cap"><span class="hcat">' + labelOf(en) + '</span>' +
          '<h2><a href="' + linkOf(en) + '">' + titleOf(en).replace(/</g,'&lt;') + '</a></h2></div>';
        slider.insertBefore(s, $('#heroPrev'));
      });
      var dots = $('#heroDots'), slides = $$('.hero-slide', slider), cur = 0, timer;
      slides.forEach(function(_, i){
        var b = document.createElement('button');
        if(i===0) b.className='active';
        b.setAttribute('aria-label','Slide '+(i+1));
        b.addEventListener('click', function(){ go(i); restart(); });
        dots.appendChild(b);
      });
      function go(i){
        slides[cur].classList.remove('active'); dots.children[cur].classList.remove('active');
        cur = (i + slides.length) % slides.length;
        slides[cur].classList.add('active'); dots.children[cur].classList.add('active');
      }
      function restart(){ clearInterval(timer); timer = setInterval(function(){ go(cur+1); }, 5000); }
      var pv=$('#heroPrev'), nx=$('#heroNext');
      if(pv) pv.addEventListener('click', function(){ go(cur-1); restart(); });
      if(nx) nx.addEventListener('click', function(){ go(cur+1); restart(); });
      restart();
      watchReveals();
    });
  }

  /* Terpopuler */
  var pop = $('#popularPosts');
  if(pop){
    feed('/feeds/posts/default?alt=json&max-results=5').then(function(es){
      if(!es.length){ pop.innerHTML = '<p style="color:var(--muted);font-size:13px">Belum ada postingan.</p>'; return; }
      pop.innerHTML = es.map(function(en, i){
        var im = thumb(en,'s200');
        return '<div class="pop-item"><span class="pop-num">' + (i+1) + '</span>' +
          (im ? '<img src="' + im + '" alt="" loading="lazy"/>' : '') +
          '<a href="' + linkOf(en) + '">' + titleOf(en).replace(/</g,'&lt;') + '</a></div>';
      }).join('');
    });
  }

  /* Berita terkait (halaman artikel) */
  var rel = $('#relatedGrid');
  if(rel && postBody){
    var here = location.href.split('#')[0];
    feed('/feeds/posts/default?alt=json&max-results=7').then(function(es){
      var items = es.filter(function(en){ return linkOf(en).split('#')[0] !== here; }).slice(0,3);
      rel.innerHTML = items.map(function(en){
        var im = thumb(en,'s600');
        return '<article class="post-card reveal visible">' +
          '<a class="card-media" href="' + linkOf(en) + '">' +
          (im ? '<img src="' + im + '" alt="" loading="lazy"/>' : '<div class="card-media-fallback">KabarViral</div>') +
          '<span class="card-cat">' + labelOf(en) + '</span></a>' +
          '<div class="card-body"><h3 class="card-title"><a href="' + linkOf(en) + '">' +
          titleOf(en).replace(/</g,'&lt;') + '</a></h3></div></article>';
      }).join('');
    });
  }

  /* Sisipkan slot iklan di tengah artikel (setelah paragraf ke-2) */
  if(postBody){
    var ps = postBody.getElementsByTagName('p');
    if(ps.length > 2){
      var mid = document.createElement('div');
      mid.className = 'ad-slot';
      mid.innerHTML = '<span class="ad-label">Iklan tengah artikel — tempel kode AdSense di sini</span>';
      ps[1].parentNode.insertBefore(mid, ps[2]);
    }
  }
})();
//
